function projectNote(id, date, updated, title, category, tags, summary, origin, spark, reflection, repo, branch, extraLinks) {
  const links = [
    { label: "Repository", url: "https://github.com/johnnietse/" + repo },
    { label: "Commit history", url: "https://github.com/johnnietse/" + repo + "/commits/" + (branch || "main") },
    { label: "Branches", url: "https://github.com/johnnietse/" + repo + "/branches/all" }
  ];
  if (extraLinks) extraLinks.forEach(function (item) { links.push(item); });
  const projectGroup = ["AutoDrive_all_repos", "LS-dbc-autonomous-mode"].includes(repo) ? "Design team · AutoDrive II" :
    /coursework|course project|capstone/i.test(category) ? "Coursework & capstone" :
    /research|study/i.test(category) ? "Research & experiments" :
    /fellowship|freelance/i.test(category) ? "Fellowship & professional work" :
    /team|design/i.test(category) ? "Design & team projects" :
    /proposal/i.test(category) ? "Proposals" : "Independent & interest projects";
  return {
    id: id, date: date, updated: updated || date, title: title, category: category,
    tags: tags, summary: summary, origin: origin, spark: spark, reflection: reflection,
    links: links,
    primaryWorkBranch: id === "epp-energy-routing" ? branch : "",
    repositoryDefaultBranch: id === "epp-energy-routing" ? "main" : "",
    repo: "johnnietse/" + repo,
    organization: "johnnietse",
    projectGroup: projectGroup,
    entryType: "Project"
  };
}

function contributionNote(id, date, updated, title, tags, summary, origin, spark, reflection, links) {
  const repositoryLink = (links || []).map(function (item) {
    return item.url && item.url.match(/^https:\/\/github\.com\/[^/]+\/[^/]+/);
  }).filter(Boolean)[0];
  const repository = repositoryLink ? repositoryLink[0].replace("https://github.com/", "").split("/").slice(0, 2).join("/") : "";
  const isWriting = !repository && (tags || []).includes("Writing");
  return {
    id: id, date: date, updated: updated || date, title: title, category: repository ? "Open source" : isWriting ? "Writing" : "Project",
    tags: repository ? ["Open source"].concat(tags) : tags, summary: summary, origin: origin, spark: spark,
    reflection: reflection, links: links, repo: repository,
    organization: repository ? repository.split("/")[0] : "",
    projectGroup: repository ? repository.split("/")[1] : isWriting ? "Writing and portfolio notes" : "Independent & interest projects",
    entryType: repository ? "Open source" : isWriting ? "Writing" : "Project"
  };
}

